static volatile unsigned salt;
static __attribute__((noinline)) unsigned mix(unsigned x) {
  return (x ^ (x >> 7)) * 17u + salt;
}
__attribute__((noinline)) unsigned host_check(unsigned n) {
  unsigned value = 0;
  for (unsigned i = 0; i < n; ++i) {
    if (i & 1) value += mix(i); else value ^= mix(i + 3);
  }
  return value;
}

